import React, {
  createContext,
  CSSProperties,
  ReactNode,
  useContext,
} from "react";
import { ColProps } from "@arco-design/web-react";
import classNames from "classnames";
import { usePrefixCls } from "../__builtins__";
import { SpaceSize } from "@arco-design/web-react/es/Space";

export interface IFormLayoutProps {
  style?: CSSProperties;
  className?: string | string[];
  prefixCls?: string;
  colon?: boolean;
  labelCol?: number;
  wrapperCol?: number;
  wrapperWidth?: number | string;
  labelWidth?: number | string;
  labelAlign?: "left" | "right";
  /**
   * @zh 标签换⾏，否则出现省略号，hover 有 tooltip
   */
  labelWrap?: boolean;
  /**
   * @zh formItem 标签换⾏，否则出现省略号，hover 有 tooltip
   */
  layout?: "horizontal" | "vertical";
  requiredSymbol?: boolean | { position: "start" | "end" };
  /**
   * @zh 不同尺寸。
   * @en size of form
   */
  size?: "mini" | "small" | "default" | "large";

  /**
   * @zh Space 的间距设置
   */
  spaceSize?: SpaceSize | SpaceSize[];
  /**
   * @zh 问号提示
   */
  tooltip?: {
    content?: ReactNode;
    tooltipIcon?: ReactNode;
    tooltipLayout?: "icon" | "text";
    customRender?: () => ReactNode;
  };
  /**
   * @zh helper 的提示方式为 popover 还是正常展示到组件下面
   */
  helpLayout?: "popover" | "normal";
  gridColumnGap?: number;
  gridRowGap?: number;
  requiredAlign?: boolean;

  // 先只考虑这么多，formItem 或者其它组件要增加再增加
  // wrapperAlign?: 'right' | 'left' | ('right' | 'left')[];
  // wrapperWidth?: number;
  // wrapperWrap?: boolean;
  // fullness?: boolean;
  // size?: 'small' | 'default' | 'large';
  // direction?: 'rtl' | 'ltr';
  // inset?: boolean;
  // shallow?: boolean;
  // tooltipLayout?: 'icon' | 'text';
  // tooltipIcon?: React.ReactNode;
  // feedbackLayout?: 'loose' | 'terse' | 'popover' | 'none';
  // bordered?: boolean;
  // breakpoints?: number[];
  // spaceGap?: number;
}

export const FormLayoutContext = createContext<IFormLayoutProps>({
  layout: "horizontal",
  labelCol: 5,
  labelAlign: "right",
  wrapperCol: 19,
  requiredSymbol: true,
  size: "default",
  colon: true,
  helpLayout: "normal",
});

export const useFormLayout = () => useContext(FormLayoutContext);

export const FormLayout: React.FC<React.PropsWithChildren<IFormLayoutProps>> & {
  useFormLayout: () => IFormLayoutProps;
} = (props) => {
  const { children, ...rest } = props;

  const formLayoutContext = useFormLayout();
  const deepLayout = {
    ...formLayoutContext,
    ...rest,
  };

  const { className, layout = "horizontal", prefixCls, style } = deepLayout;

  const layoutPrefixCls = usePrefixCls("formily-layout", { prefixCls });
  const formPrefixCls = usePrefixCls("form");
  const layoutClassName = classNames(layoutPrefixCls, {
    [`${formPrefixCls}-${layout}`]: true,
    [`${className}`]: Boolean(className),
  });

  const renderChildren = () => (
    <FormLayoutContext.Provider value={deepLayout}>
      {children}
    </FormLayoutContext.Provider>
  );

  return (
    <div className={layoutClassName} style={style}>
      {renderChildren()}
    </div>
  );
};

FormLayout.useFormLayout = useFormLayout;

export default FormLayout;
